  final bool dirty;
  final String assignmentId;
  final String vehicleId;
  final String driverId;
  final int dueDay;
  final int expectedMinor;

  /// Forgiven part of [expectedMinor] (garage waiver, or waived by the owner).
  final int waivedMinor;
  final String? note;
